INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (8, 'መዝሙር ክፍል', 'Choir & Hymnology Department', 'የያሬዳዊ ዜማና ቅዱሳት መዝሙራት ትምህርትና አገልግሎት ማስተባበሪያ ክፍል', '2026-10-25T19:54:45.619Z', '2026-10-25T19:54:45.619Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (9, 'ትምህርት ክፍል', 'Education Department', 'የነገረ መለኮት፣ የመጽሐፍ ቅዱስና የቤተ ክርስቲያን ሥርዓት ትምህርቶች ክፍል', '2026-10-25T19:54:45.632Z', '2026-10-25T19:54:45.632Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (10, 'ማኅበራዊ አገልግሎት ክፍል', 'Social Service Department', 'የበጎ አድራጎት፣ የልማትና የእርስ በእርስ መረዳዳት አገልግሎት ክፍል', '2026-10-25T19:54:45.645Z', '2026-10-25T19:54:45.645Z');
INSERT INTO `departments` (`id`, `nameAm`, `nameEn`, `description`, `createdAt`, `updatedAt`) VALUES (11, 'ህፃናት ክፍል', 'Children Ministry Department', 'የህፃናት መንፈሳዊ አስተዳደግ፣ ትምህርትና መርሐ ግብራት ክፍል', '2026-10-25T19:54:45.656Z', '2026-10-25T19:54:45.656Z');
