INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('570dec9c-803d-42f2-aaf6-4bde1539b477', 'ጽዮን ሆይ ደስ ይበልሽ', 'ጽዮን ሆይ ደስ ይበልሽ ንጉሥሽ ይመጣል፤ ጻድቅና አዳኝ የሆነው ጌታ።', 7, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.802Z', '2026-10-17T17:56:56.802Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('598a85b6-c779-41ed-821f-dbe4b9739d91', 'ገብርኤል አብሳሪው', 'ብስራተ ሰላምን ይዞ የመጣው፤ ገብርኤል መልአከ እግዚአብሔር ነው።', 4, 'ዘማሪ ይስሐቅ', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.742Z', '2026-10-17T17:56:56.742Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('611ac262-6954-4d2e-bd01-909fa29319fe', 'ቅዱስ ሚካኤል ሊቀ መላእክት', 'ቅዱስ ሚካኤል ቆሟል በፊታችን፤ ታዳጊ መልአክ ነው ለመከራችን።', 4, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.697Z', '2026-10-17T17:56:56.697Z');
