INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f276da5c-50a3-46bc-9b8e-c6142ab6c034', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው', 'እግዚአብሔር ብርሃኔና መድኃኒቴ ነው፤ የሚያስፈራኝ ማን ነው?', 3, 'አዕማደ ሰላም መዘምራን', NULL, NULL, 1, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.734Z', '2026-10-17T17:56:56.734Z');
INSERT INTO `mezmurs` (`id`, `title`, `lyrics`, `categoryId`, `singer`, `audioUrl`, `videoUrl`, `isPublic`, `createdBy`, `createdAt`, `updatedAt`) VALUES ('f3963eeb-b35d-4b55-9646-c2ab748f7827', 'ተወልደ ኢየሱስ በቤተ ልሔም', 'ተወልደ ኢየሱስ በቤተ ልሔም ዘይሁዳ አማኑኤል ተወልደልን', 8, 'አዕማደ ሰላም መዘምራን', '/uploads/mezmurs/audio/52e00346-af48-4040-a726-9736d1bf81b1.mp3', '/uploads/mezmurs/video/602b2292-36be-4091-8766-e5136f0434db.mp4', 1, '049b5097-0720-4f3d-97ea-f28d13c2af54', '2026-10-20T19:13:55.684Z', '2026-10-20T19:13:56.115Z');
