INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('27f8ffab-b075-42a6-af06-de669ba90ee8', 'urgent', 'አስቸኳይ የጸሎተ ምሕላ ጥሪ', 'ነገ ማለዳ 12:00 ሰዓት ሁሉም አባላት በቤተክርስቲያን እንዲገኙ ጥሪ ቀርቧል።', NULL, 1, '2026-10-20T19:13:56.865Z', NULL, '049b5097-0720-4f3d-97ea-f28d13c2af54', '2026-10-20T19:13:56.867Z', '2026-10-20T19:13:56.867Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('3ea6a392-36e5-4719-b98a-6b28a93ba8e4', 'teaching', 'ስለ አሥራትና በኩራት ትምህርት', '«በቤቴ ውስጥ መብል እንዲሆን አሥራቱን ሁሉ ወደ ጎተራ አግቡ» - ሚልክያስ ፫:፲። የክርስትና የልግስና መርሆዎች።', NULL, 0, '2026-10-17T17:56:56.892Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.892Z', '2026-10-17T17:56:56.892Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('6807c844-591a-47ae-b722-72ad17a89976', 'sinksar', 'የዕለቱ ስንክሳር ጥቅምት ፯ - 8490', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', NULL, 1, '2026-10-17T18:09:00.000Z', NULL, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:09:49.057Z', '2026-10-17T18:09:49.057Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('6b7ca6db-c408-4233-9777-fa1bcd3fceab', 'news', 'የመዘምራን ክፍል አዲስ አልበም ዝግጅት', 'የመዝሙር ክፍሉ አዲስ መንፈሳዊ ያሬዳዊ የዝማሬ አልበም ለማዘጋጀት ልምምድ ጀምሯል።', NULL, 0, '2026-10-17T17:56:56.904Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.904Z', '2026-10-17T17:56:56.904Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('87e788a6-b88f-43ae-bcf2-05017a085e98', 'sinksar', 'የዕለቱ ስንክሳር - ጥቅምት ፫', 'በዚህች ዕለት አባ ጽጌ ድንግል እና ቅዱሳን ሰማዕታት ይታሰባሉ።', '/uploads/posts/69be6cbf-c944-4baf-b3d4-487b27dd4c1a.webp', 0, '2026-10-20T19:11:57.001Z', '2026-10-20T19:13:47.001Z', '049b5097-0720-4f3d-97ea-f28d13c2af54', '2026-10-20T19:13:56.486Z', '2026-10-20T19:13:57.049Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('9303aa06-e86a-4641-934a-165900f1e887', 'event', 'ዓመታዊ የሰንበት ትምህርት ቤት የምስረታ በዓል', 'አዕማደ ሰላም ሰንበት ትምህርት ቤት የተመሰረተበትን 26ኛ ዓመት በልዩ መንፈሳዊ ድግስ እናከብራለን።', NULL, 0, '2026-10-17T17:56:56.880Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.880Z', '2026-10-17T17:56:56.880Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('985bbe20-939f-41cc-a591-0e53f54b3f0b', 'sinksar', 'የዕለቱ ስንክሳር ጥቅምት ፯ - 8643', '<p>ይህ የዕለቱ ስንክሳር ንባብና የቅዱሳን አበው ገድል ነው።</p>', NULL, 1, '2026-10-17T18:40:00.000Z', NULL, 'cdf9d8cd-14ff-4344-9de3-9a8c5a1654c1', '2026-10-17T18:40:39.966Z', '2026-10-17T18:40:39.966Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('b762ae63-f8c0-40d5-9640-bb8e0f6d3f6e', 'sinksar', 'የዕለቱ ስንክሳር፡ ጥቅምት ፪', 'በዚህች ዕለት የከበሩ ጻድቃንና ሰማዕታት መታሰቢያቸው ሆነ፤ ጸሎታቸውና ምልጃቸው ከሁላችን ጋር ይሁን።', NULL, 0, '2026-10-17T17:56:56.835Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.835Z', '2026-10-17T17:56:56.835Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('ca1c94ea-3df4-4252-856e-99b02f45419e', 'bible_reading', 'የዕለቱ የቅዱስ ወንጌል ንባብ', '«እኔ የመንገድ እውነትና ሕይወት ነኝ፤ በእኔ በቀር ወደ አብ የሚመጣ ማንም የለም» - ዮሐንስ ፲፬:፮', NULL, 0, '2026-10-17T17:56:56.848Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.848Z', '2026-10-17T17:56:56.848Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('d20b5598-387b-4066-be81-9514b46950a5', 'teaching', 'የሰንበት ትምህርት ቤት አስፈላጊነት በዘመናችን', 'ሰንበት ትምህርት ቤት የቤተ ክርስቲያን የጀርባ አጥንት ናት። ሕፃናትና ወጣቶች በእውነተኛው ሃይማኖትና ምግባር የሚታነጹበት ማዕከል ናት።', NULL, 0, '2026-10-17T17:56:56.866Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.866Z', '2026-10-17T17:56:56.866Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('fe551855-4ec4-4569-bd32-9744e4dfb366', 'sinksar', 'የጥቅምት ወር የበዓላት ማውጫ', 'በዚህ ወር የሚከበሩ ዓበይትና ንዑሳን የቅዱሳን በዓላት ዝርዝርና መርሐ ግብራቸው።', NULL, 0, '2026-10-17T17:56:56.898Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.898Z', '2026-10-17T17:56:56.898Z');
INSERT INTO `posts` (`id`, `type`, `title`, `body`, `imageUrl`, `isUrgent`, `publishAt`, `expiresAt`, `authorId`, `createdAt`, `updatedAt`) VALUES ('fe6a11c0-fd9e-4247-a702-d0316ebc7724', 'news', 'የአዲስ ተማሪዎች ምዝገባ ተጀመረ', 'ለ2019 ዓ.ም የትምህርት ዘመን ከደረጃ ፩ እስከ ፬ የአዲስ ተማሪዎች ምዝገባ በይፋ ተከፍቷል።', NULL, 0, '2026-10-17T17:56:56.886Z', NULL, 'efc72369-5c7e-4a1a-938d-2f3ec2a45aa4', '2026-10-17T17:56:56.886Z', '2026-10-17T17:56:56.886Z');
